import java.util.PriorityQueue;
class LUPrefix {
    private PriorityQueue<Integer> pq = new PriorityQueue<>();
    private int ans = 0;

    public LUPrefix(int n) {}

    public void upload(int video) {
        pq.offer(video);
    }

    public int longest() {
        while (!pq.isEmpty() && pq.peek() == ans + 1) {
            pq.poll();
            ans++;
        }
        return ans;
    }
}

